UPDATE photo_work
SET work_title = #{workTitle}, photographer = #{photographer},
    shoot_type = #{shootType}, studio = #{studio},
    shoot_date = #{shootDate}, retouch_hours = #{retouchHours},
    price = #{price}, status = #{status}
WHERE work_id = #{workId}

mapper.select:
SELECT  FROM photo_work

    
        work_title LIKE CONCAT('%', #{workTitle}, '%')
    
    
        AND photographer LIKE CONCAT('%', #{photographer}, '%')
    
    
        AND shoot_type = #{shootType}
    
    
        AND status = #{status}
    

ORDER BY work_id

